package com.zenix.musicplayer;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class PersonalFeatureFormat {
    static final int MAX_BYTES=12*1024*1024;
    static JSONObject empty(){return Json.obj("schema",1,"revision",0,"bookmarks",new JSONArray(),"lyrics",new JSONArray(),"journal",new JSONArray());}
    private static String text(Object value,int max)throws Exception{if(!(value instanceof String)||((String)value).length()>max)throw new Exception("私人资料文本无效或过长");return (String)value;}
    static JSONObject reference(JSONObject value)throws Exception{
        if(value==null)throw new Exception("歌曲资料无效");String source=value.optString("source","local");if(!List.of("local","online","custom").contains(source))source="local";
        double duration=value.optDouble("duration",0);if(!Double.isFinite(duration)||duration<0)duration=0;
        return Json.obj("id",text(value.opt("id"),24000),"title",text(value.opt("title"),300),"artist",text(value.optString("artist"),300),"album",text(value.optString("album"),300),"duration",Math.min(duration,86400),"source",source,"providerId",text(value.optString("providerId"),120),"remoteId",text(value.optString("remoteId"),20000));
    }
    static String key(JSONObject value){return value.optString("source")+'\0'+value.optString("providerId")+'\0'+(value.optString("remoteId").isEmpty()?value.optString("id"):value.optString("remoteId"));}
    static JSONObject clean(JSONObject value)throws Exception{
        if(value==null)return empty();if(value.optInt("schema")!=1||!(value.opt("revision") instanceof Number)||value.optDouble("revision")<0||value.optDouble("revision")!=Math.floor(value.optDouble("revision")))throw new Exception("私人资料格式不受支持，原资料已保留");
        JSONArray bookmarks=value.getJSONArray("bookmarks"),lyrics=value.getJSONArray("lyrics"),journal=value.getJSONArray("journal");if(bookmarks.length()>5000||lyrics.length()>1000||journal.length()>50)throw new Exception("私人资料数量超过限制");
        JSONArray cleanBookmarks=new JSONArray(),cleanLyrics=new JSONArray();Set<String> ids=new HashSet<>();
        for(int i=0;i<bookmarks.length();i++){JSONObject row=bookmarks.getJSONObject(i);String id=text(row.opt("id"),100);double seconds=row.optDouble("seconds",Double.NaN);if(!ids.add(id)||!Double.isFinite(seconds)||seconds<0||seconds>86400||!Double.isFinite(row.optDouble("createdAt",Double.NaN)))throw new Exception("书签格式无效");cleanBookmarks.put(Json.obj("id",id,"track",reference(row.getJSONObject("track")),"seconds",seconds,"note",text(row.optString("note"),2000),"lyric",text(row.optString("lyric"),2000),"createdAt",row.getDouble("createdAt")));}
        for(int i=0;i<lyrics.length();i++){JSONObject row=lyrics.getJSONObject(i);cleanLyrics.put(Json.obj("track",reference(row.getJSONObject("track")),"text",text(row.opt("text"),120000),"updatedAt",row.optDouble("updatedAt",0)));}
        for(int i=0;i<journal.length();i++){JSONObject row=journal.getJSONObject(i);text(row.opt("id"),100);text(row.opt("label"),200);JSONArray changes=row.getJSONArray("changes");if(changes.length()>1000)throw new Exception("修改记录过大");for(int j=0;j<changes.length();j++){JSONObject change=changes.getJSONObject(j);text(change.opt("id"),100);for(String side:List.of("before","after")){if(!change.has(side))throw new Exception("修改记录不完整");if(!change.isNull(side)){JSONObject list=change.getJSONObject(side);text(list.opt("name"),100);if(list.getJSONArray("tracks").length()>10000)throw new Exception("歌单快照过大");}}}}
        JSONObject result=Json.obj("schema",1,"revision",value.getLong("revision"),"bookmarks",cleanBookmarks,"lyrics",cleanLyrics,"journal",new JSONArray(journal.toString()));if(result.toString().getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new Exception("私人资料超过12 MiB");return result;
    }
    static JSONObject mergePreview(JSONObject current,JSONObject incoming)throws Exception{Map<String,JSONObject> old=new HashMap<>();JSONArray rows=current.getJSONArray("bookmarks");for(int i=0;i<rows.length();i++)old.put(rows.getJSONObject(i).getString("id"),rows.getJSONObject(i));int added=0,duplicates=0,conflicts=0;rows=incoming.getJSONArray("bookmarks");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),previous=old.get(row.getString("id"));if(previous==null)added++;else if(BackupFormat.canonical(previous).equals(BackupFormat.canonical(row)))duplicates++;else conflicts++;}return Json.obj("added",added,"duplicates",duplicates,"conflicts",conflicts,"lyrics",incoming.getJSONArray("lyrics").length(),"revision",current.optLong("revision"));}
    static JSONObject merge(JSONObject current,JSONObject incoming)throws Exception{JSONObject next=Json.copy(current);JSONArray values=next.getJSONArray("bookmarks"),rows=incoming.getJSONArray("bookmarks");Map<String,JSONObject> ids=new HashMap<>();for(int i=0;i<values.length();i++)ids.put(values.getJSONObject(i).getString("id"),values.getJSONObject(i));for(int i=0;i<rows.length();i++){JSONObject row=Json.copy(rows.getJSONObject(i)),old=ids.get(row.getString("id"));if(old==null){values.put(row);ids.put(row.getString("id"),row);}else if(!BackupFormat.canonical(old).equals(BackupFormat.canonical(row))){Json.put(row,"id",UUID.randomUUID().toString());values.put(row);ids.put(row.getString("id"),row);}}
        Set<String> keys=new HashSet<>();JSONArray lyrics=next.getJSONArray("lyrics"),other=incoming.getJSONArray("lyrics");for(int i=0;i<lyrics.length();i++)keys.add(key(lyrics.getJSONObject(i).getJSONObject("track")));for(int i=0;i<other.length();i++)if(keys.add(key(other.getJSONObject(i).getJSONObject("track"))))lyrics.put(other.get(i));Json.put(next,"revision",current.optLong("revision")+1);return clean(next);}
    private static Map<String,JSONObject> lists(JSONObject personal)throws Exception{Map<String,JSONObject> result=new LinkedHashMap<>();JSONArray values=personal.optJSONArray("playlists");if(values!=null)for(int i=0;i<values.length();i++){JSONObject row=values.getJSONObject(i);result.put(row.getString("id"),row);}return result;}
    static JSONObject record(JSONObject raw,JSONObject before,JSONObject after,String label)throws Exception{
        Map<String,JSONObject> old=lists(before),next=lists(after);Set<String> ids=new LinkedHashSet<>(old.keySet());ids.addAll(next.keySet());JSONArray changes=new JSONArray();
        for(String id:ids)if(!BackupFormat.canonical(old.get(id)).equals(BackupFormat.canonical(next.get(id))))changes.put(Json.obj("id",id,"before",old.get(id)==null?JSONObject.NULL:old.get(id),"after",next.get(id)==null?JSONObject.NULL:next.get(id)));
        if(changes.length()==0)return raw;JSONObject state=clean(raw),entry=Json.obj("id",UUID.randomUUID().toString(),"label",label,"createdAt",System.currentTimeMillis(),"undone",false,"changes",changes);JSONArray journal=new JSONArray().put(entry),previous=state.getJSONArray("journal");for(int i=0;i<previous.length()&&journal.length()<50;i++)journal.put(previous.get(i));Json.put(state,"journal",journal);Json.put(state,"revision",state.optLong("revision")+1);return clean(state);
    }
}
